import{_ as a,o as t,c as i,a7 as s}from"./chunks/framework.BJyR0VjM.js";const g=JSON.parse('{"title":"How Launching Works","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/how-launching-works.md","filePath":"documentation/how-launching-works.md"}'),r={name:"documentation/how-launching-works.md"};function o(n,e,h,l,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="how-launching-works" tabindex="-1">How Launching Works <a class="header-anchor" href="#how-launching-works" aria-label="Permalink to “How Launching Works”">​</a></h1><p>When you run <code>java -jar YggUtils.jar</code>, several things happen in order before your Minecraft server starts.</p><h2 id="startup-sequence" tabindex="-1">Startup Sequence <a class="header-anchor" href="#startup-sequence" aria-label="Permalink to “Startup Sequence”">​</a></h2><h3 id="_1-meta-directory" tabindex="-1">1. Meta directory <a class="header-anchor" href="#_1-meta-directory" aria-label="Permalink to “1. Meta directory”">​</a></h3><p>YggUtils ensures a <code>meta/</code> directory exists in the working directory. This is where it stores <code>authlibinjector.jar</code>.</p><h3 id="_2-authlib-injector-check" tabindex="-1">2. Authlib-injector check <a class="header-anchor" href="#_2-authlib-injector-check" aria-label="Permalink to “2. Authlib-injector check”">​</a></h3><p>If <code>meta/authlibinjector.jar</code> is not present, YggUtils downloads it automatically from the official GitHub release. If the download fails, YggUtils exits with code <code>1</code> and prints an error.</p><h3 id="_3-config-validation" tabindex="-1">3. Config validation <a class="header-anchor" href="#_3-config-validation" aria-label="Permalink to “3. Config validation”">​</a></h3><p>YggUtils reads <code>YggUtils.yml</code> and checks:</p><ul><li>The file exists</li><li>Both <code>authserver</code> and <code>serverfile</code> are non-empty</li><li>The file named in <code>serverfile</code> actually exists on disk</li></ul><p>If the config file is missing, it is generated with empty values and YggUtils exits with code <code>0</code>, prompting you to fill it in. If values are empty, YggUtils warns you and exits with code <code>0</code> without starting the server.</p><h3 id="_4-server-launch" tabindex="-1">4. Server launch <a class="header-anchor" href="#_4-server-launch" aria-label="Permalink to “4. Server launch”">​</a></h3><p>Once config is valid, YggUtils launches your server using <code>ProcessBuilder</code> with the following effective command:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -javaagent:meta/authlibinjector.jar=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">authserver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverfil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nogui</span></span></code></pre></div><p>The <code>nogui</code> flag is always appended. stderr is merged into stdout so all output goes through a single stream.</p><h3 id="_5-console-forwarding" tabindex="-1">5. Console forwarding <a class="header-anchor" href="#_5-console-forwarding" aria-label="Permalink to “5. Console forwarding”">​</a></h3><p>A background thread reads from your stdin and writes each line directly to the server process&#39;s stdin. This means any command you type in the terminal is forwarded to the running server as-is.</p><h3 id="_6-output-piping" tabindex="-1">6. Output piping <a class="header-anchor" href="#_6-output-piping" aria-label="Permalink to “6. Output piping”">​</a></h3><p>A second background thread reads the server&#39;s stdout line by line, prints each line to your console, and appends it to <code>YggUtils-server.log</code>.</p><h2 id="the-restart-loop" tabindex="-1">The Restart Loop <a class="header-anchor" href="#the-restart-loop" aria-label="Permalink to “The Restart Loop”">​</a></h2><p>After launching, YggUtils waits for the server process to exit. The exit code determines what happens next:</p><table tabindex="0"><thead><tr><th>Exit Code</th><th>Meaning</th><th>Action</th></tr></thead><tbody><tr><td><code>0</code></td><td>Clean shutdown (e.g. <code>/stop</code>)</td><td>YggUtils exits normally</td></tr><tr><td>Non-zero</td><td>Crash or unexpected exit</td><td>Wait 3 seconds, then relaunch</td></tr></tbody></table><p>This loop continues until either a clean shutdown occurs or YggUtils itself is terminated.</p><h2 id="effective-jvm-command" tabindex="-1">Effective JVM Command <a class="header-anchor" href="#effective-jvm-command" aria-label="Permalink to “Effective JVM Command”">​</a></h2><p>The exact command YggUtils runs is always:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>java -javaagent:meta/authlibinjector.jar=&lt;authserver&gt; -jar &lt;serverfile&gt; nogui</span></span></code></pre></div><p>YggUtils does not pass any additional JVM flags. If you need custom flags (heap size, GC tuning, etc.), you should configure those at the hosting level or through a startup script that invokes YggUtils with those flags applied to it — note that flags on the YggUtils invocation itself do not pass through to the server process.</p>',27)])])}const u=a(r,[["render",o]]);export{g as __pageData,u as default};
